ssize_t device_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    struct device_info *dev_info;
    struct element_info *elem;
    ssize_t bytes_written = 0;
    int ret;

    mutex_lock(&active_device_lock);

    dev_info = get_active_device();
    if (!dev_info || !dev_info->is_connected) {
        mutex_unlock(&active_device_lock);
        return -ENODEV;
    }

    elem = allocate_element_info();
    if (!elem) {
        mutex_unlock(&active_device_lock);
        return -ENOMEM;
    }

    ret = copy_from_user(elem->data, buf, count);
    if (ret) {
        free_element_info(elem);
        mutex_unlock(&active_device_lock);
        return -EFAULT;
    }

    update_sequence_number(elem);
    queue_element_for_processing(elem);

    bytes_written = count;
    dev_info->position += count;
    put_device_reference(dev_info);
    mutex_unlock(&active_device_lock);

    return bytes_written;
}

