ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    struct dev_info *dev_info;
    struct element_info *element;
    ssize_t ret = -EFAULT;

    if (!filp || !buf || !count || !fpos)
        return -EINVAL;

    dev_info = get_active_device();
    if (!dev_info)
        return -ENODEV;

    element = allocate_element_info();
    if (!element)
        return -ENOMEM;

    if (copy_from_user(element->data, buf, count)) {
        kfree(element);
        return -EFAULT;
    }

    element->length = count;
    element->seq_num = ++dev_info->write_seq;
    queue_element(dev_info, element);

    ret = count;
    *fpos += count;

    release_dev_reference(dev_info);
    return ret;
}

ssize_t device_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    struct device_info *dev_info;
    struct element_info *elem;
    ssize_t bytes_written = 0;
    int err = 0;

    if (!filp || !buf || !count || !fpos)
        return -EINVAL;

    dev_info = filp->private_data;
    if (!dev_info)
        return -EFAULT;

    if (!dev_info->active) {
        return -ENODEV;
    }

    elem = kmalloc(sizeof(*elem), GFP_KERNEL);
    if (!elem) {
        return -ENOMEM;
    }

    mutex_lock(&dev_info->lock);

    if (!dev_info->connected) {
        mutex_unlock(&dev_info->lock);
        kfree(elem);
        return -ENODEV;
    }

    if (copy_from_user(elem->data, buf, count)) {
        mutex_unlock(&dev_info->lock);
        kfree(elem);
        return -EFAULT;
    }

    elem->length = count;
    elem->sequence = dev_info->sequence++;
    elem->status = ELEMENT_READY;

    if (!queue_element(dev_info, elem)) {
        mutex_unlock(&dev_info->lock);
        kfree(elem);
        return -EIO;
    }

    bytes_written = count;
    dev_info->bytes_written += count;

    mutex_unlock(&dev_info->lock);
    return bytes_written;
}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    struct dev_info *dev;
    struct elem_info *elem;
    ssize_t bytes_written = 0;
    int ret;

    dev = get_active_device();
    if (!dev) {
        return -ENODEV;
    }

    elem = alloc_elem_info();
    if (!elem) {
        put_device(dev);
        return -ENOMEM;
    }

    ret = copy_from_user(elem->data, buf, count);
    if (ret) {
        free_elem_info(elem);
        put_device(dev);
        return -EFAULT;
    }

    elem->seq_num = get_next_seq_num();
    queue_elem(dev->queue, elem);
    bytes_written = count;

    free_elem_info(elem);
    put_device(dev);
    return bytes_written;
}
